#!/usr/bin/env node

import { build } from './generator';

async function main(): Promise<void> {
  const args = process.argv.slice(2);

  if (args.length === 0 || args[0] !== 'build') {
    console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
    process.exit(1);
  }

  let contentDir = './content';
  let outputDir = './dist';

  for (let i = 1; i < args.length; i++) {
    if (args[i] === '--content' && args[i + 1]) {
      contentDir = args[i + 1];
      i++;
    } else if (args[i] === '--output' && args[i + 1]) {
      outputDir = args[i + 1];
      i++;
    }
  }

  try {
    await build(contentDir, outputDir);
    console.log(`✓ Site built successfully to ${outputDir}`);
  } catch (error) {
    if (error instanceof Error) {
      console.error(`✗ Error: ${error.message}`);
    } else {
      console.error('✗ Unknown error occurred');
    }
    process.exit(1);
  }
}

main();

export { build, generatePages, generatePageHtml, generateIndexHtml, parseMarkdownFile, readMarkdownFiles } from './generator';
export { parseFrontmatter } from './frontmatter';
export { markdownToHtml } from './markdown';
export type { Frontmatter, ParsedMarkdown } from './frontmatter';
export type { PageData } from './generator';

import { parseFrontmatter } from './frontmatter';

describe('Frontmatter Parser', () => {
  it('should parse valid YAML frontmatter', () => {
    const markdown = `---
title: Hello World
date: 2023-01-01
tags: [javascript, typescript]
---
# Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.title).toBe('Hello World');
    expect(result.frontmatter.date).toBe('2023-01-01');
    expect(result.frontmatter.tags).toEqual(['javascript', 'typescript']);
    expect(result.content).toBe('# Content');
  });

  it('should handle markdown without frontmatter', () => {
    const markdown = '# Just a heading\n\nSome content';

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter).toEqual({});
    expect(result.content).toBe('# Just a heading\n\nSome content');
  });

  it('should parse boolean values', () => {
    const markdown = `---
title: Test
published: true
draft: false
---
Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.published).toBe(true);
    expect(result.frontmatter.draft).toBe(false);
  });

  it('should parse numeric values', () => {
    const markdown = `---
title: Test
count: 42
rating: 3.5
---
Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.count).toBe(42);
    expect(result.frontmatter.rating).toBe(3.5);
  });

  it('should parse quoted strings', () => {
    const markdown = `---
title: "My Title"
description: "A longer description"
---
Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.title).toBe('My Title');
    expect(result.frontmatter.description).toBe('A longer description');
  });

  it('should parse arrays with mixed types', () => {
    const markdown = `---
tags: [tag1, tag2, tag3]
numbers: [1, 2, 3]
---
Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.tags).toEqual(['tag1', 'tag2', 'tag3']);
    expect(result.frontmatter.numbers).toEqual(['1', '2', '3']);
  });

  it('should handle missing frontmatter end marker', () => {
    const markdown = `---
title: Test
no closing marker
# Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter).toEqual({});
    expect(result.content).toBe(`---
title: Test
no closing marker
# Content`);
  });

  it('should handle empty frontmatter', () => {
    const markdown = `---
---
# Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter).toEqual({});
    expect(result.content).toBe('# Content');
  });

  it('should ignore YAML comments', () => {
    const markdown = `---
title: Test
# this is a comment
author: John
---
Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.title).toBe('Test');
    expect(result.frontmatter.author).toBe('John');
    expect(result.frontmatter['# this is a comment']).toBeUndefined();
  });

  it('should handle null values', () => {
    const markdown = `---
title: Test
empty: null
---
Content`;

    const result = parseFrontmatter(markdown);

    expect(result.frontmatter.empty).toBeNull();
  });

  it('should trim content properly', () => {
    const markdown = `---
title: Test
---

# Content with leading blank line
More content`;

    const result = parseFrontmatter(markdown);

    expect(result.content).toBe('# Content with leading blank line\nMore content');
  });
});

import { markdownToHtml } from './markdown';

describe('Markdown to HTML', () => {
  it('should convert heading to HTML', () => {
    const md = '# Hello World';
    const html = markdownToHtml(md);
    expect(html).toContain('<h1>Hello World</h1>');
  });

  it('should convert paragraph to HTML', () => {
    const md = 'This is a paragraph.';
    const html = markdownToHtml(md);
    expect(html).toContain('<p>This is a paragraph.</p>');
  });

  it('should convert bold text', () => {
    const md = 'This is **bold** text.';
    const html = markdownToHtml(md);
    expect(html).toContain('<strong>bold</strong>');
  });

  it('should convert italic text', () => {
    const md = 'This is *italic* text.';
    const html = markdownToHtml(md);
    expect(html).toContain('<em>italic</em>');
  });

  it('should convert links', () => {
    const md = 'Check out [my site](https://example.com)';
    const html = markdownToHtml(md);
    expect(html).toContain('<a href="https://example.com">my site</a>');
  });

  it('should convert lists', () => {
    const md = `- Item 1
- Item 2
- Item 3`;
    const html = markdownToHtml(md);
    expect(html).toContain('<ul>');
    expect(html).toContain('<li>Item 1</li>');
    expect(html).toContain('</ul>');
  });

  it('should convert code blocks', () => {
    const md = '```\nconst x = 42;\n```';
    const html = markdownToHtml(md);
    expect(html).toContain('<code>');
    expect(html).toContain('const x = 42;');
  });

  it('should convert inline code', () => {
    const md = 'Use `const` to declare variables.';
    const html = markdownToHtml(md);
    expect(html).toContain('<code>const</code>');
  });

  it('should convert blockquotes', () => {
    const md = '> This is a quote';
    const html = markdownToHtml(md);
    expect(html).toContain('<blockquote>');
    expect(html).toContain('This is a quote');
  });

  it('should handle multiple paragraphs', () => {
    const md = `First paragraph.

Second paragraph.

Third paragraph.`;
    const html = markdownToHtml(md);
    const matches = html.match(/<p>/g);
    expect(matches?.length).toBe(3);
  });

  it('should handle complex markdown', () => {
    const md = `# Main Heading

This is a paragraph with **bold** and *italic*.

## Sub-heading

- List item 1
- List item 2

> A quote for emphasis

\`\`\`
code block
\`\`\``;
    const html = markdownToHtml(md);
    expect(html).toContain('<h1>Main Heading</h1>');
    expect(html).toContain('<h2>Sub-heading</h2>');
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<ul>');
    expect(html).toContain('<blockquote>');
  });
});

import fs from 'fs';
import path from 'path';
import {
  readMarkdownFiles,
